 boolean sysDark(){return (getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;}int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w,h);}LinearLayout.LayoutParams lp(int w,int h,float wt){return new LinearLayout.LayoutParams(w,h,wt);}TextView tv(int s,boolean b,int c){TextView t=new TextView(this);t.setTextSize(s);t.setTextColor(c);t.setGravity(17);t.setPadding(dp(4),dp(5),dp(4),dp(5));if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}Button bt(String s){Button b=new Button(this);b.setText(s);b.setTextSize(12);return b;}
