 void inc(){int tg=target();if(fin||cnt>=tg){fin=true;save();upd();toast("کامل شده؛ بازنشانی کنید.");return;}cnt++;total++;today++;pulse(12);if(cnt>=tg){if(isF()&&st<2){st++;cnt=0;toast("مرحله بعدی: "+f[st][0]);}else{done++;todayDone++;fin=true;pulse(80);toast("ذکر کامل شد، قبول باشد");}}saveDay();save();upd();}
