 void customOps(int w){String[] o={"ویرایش","حذف","فقط انتخاب"};new AlertDialog.Builder(this).setTitle(z().t).setItems(o,(d,x)->{if(x==0)edit(z(),w-this.d.size());if(x==1)del(w-this.d.size());}).show();}void del(int ci){if(ci<0||ci>=cu.size())return;new AlertDialog.Builder(this).setTitle("حذف ذکر").setPositiveButton("حذف",(d,w)->{cu.remove(ci);idx=0;cnt=0;fin=false;saveCu();save();upd();}).setNegativeButton("انصراف",null).show();}
 void goals(){if(isF()){toast("تسبیحات مرحله‌ای است.");return;}String[] g={"۱۰","۳۳","۱۰۰","۳۱۳","۱۰۰۰","۱۴۰۰۰","عدد دلخواه"};int[] v={10,33,100,313,1000,14000,0};new AlertDialog.Builder(this).setTitle("هدف یا ختم").setItems(g,(d,w)->{if(v[w]>0)setGoal(v[w]);else goalEdit();}).show();}void setGoal(int g){z().g=g;if(z().u)saveCu();cnt=0;fin=false;save();upd();}void goalEdit(){EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setText(String.valueOf(z().g));e.setGravity(17);new AlertDialog.Builder(this).setTitle("هدف دلخواه").setView(e).setPositiveButton("ثبت",(d,w)->setGoal(parse(e.getText().toString(),z().g))).setNegativeButton("انصراف",null).show();}
