 void stats(){String m="امروز: "+nf.format(today)+" ذکر\nتکمیل امروز: "+nf.format(todayDone)+" هدف\n\nکل ذکرها: "+nf.format(total)+"\nکل هدف‌های کامل‌شده: "+nf.format(done)+"\n\nذکر فعلی: "+z().t+"\nباقی‌مانده: "+nf.format(Math.max(0,target()-cnt));new AlertDialog.Builder(this).setTitle("آمار آرام").setMessage(m).setPositiveButton("باشه",null).setNegativeButton("پاک‌کردن",(d,w)->clear()).show();}void clear(){new AlertDialog.Builder(this).setTitle("تأیید").setMessage("آمار پاک شود؟").setPositiveButton("پاک کن",(d,w)->{total=done=today=todayDone=0;saveDay();save();upd();}).setNegativeButton("انصراف",null).show();}
 int target(){return isF()?Integer.parseInt(f[Math.max(0,Math.min(st,2))][2]):z().g;}void upd(){Z z=z();int tg=target(),p=Math.min(100,cnt*100/Math.max(1,tg));day.setText("ذکرشمار • "+key());title.setText(z.t);if(isF()){arabic.setText(f[st][1]);sub.setText("مرحله "+nf.format(st+1)+" از ۳: "+f[st][0]);}else{arabic.setText(z.a);sub.setText(z.s);}counter.setText(nf.format(cnt));goal.setText(nf.format(cnt)+" / "+nf.format(tg)+" • باقی‌مانده: "+nf.format(Math.max(0,tg-cnt)));prog.setProgress(p);pct.setText(nf.format(p)+"٪");stats.setText("امروز: "+nf.format(today)+" | کل: "+nf.format(total));hint.setText("دکمه صدا: شمارش/کم‌کردن • لمس طولانی: کسر");main.setText((fin||cnt>=tg)?"کامل شد — بازنشانی کنید":"ذکر بگو");main.setEnabled(!(fin||cnt>=tg));if(vibB!=null)vibB.setText(vib?"لرزش روشن":"لرزش خاموش");if(keepB!=null)keepB.setText(keep?"صفحه روشن":"صفحه عادی");if(modeB!=null)modeB.setText(one?"خروج از ساده":"حالت ساده");}
 void pulse(int ms){if(vib)try{((Vibrator)getSystemService(VIBRATOR_SERVICE)).vibrate(ms);}catch(Exception e){}}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}String key(){Calendar c=Calendar.getInstance();int gy=c.get(Calendar.YEAR),gm=c.get(Calendar.MONTH)+1,gd=c.get(Calendar.DAY_OF_MONTH);int[] j=jalali(gy,gm,gd);return nf.format(j[0])+"/"+nf.format(j[1])+"/"+nf.format(j[2]);}int[] jalali(int gy,int gm,int gd){int[] gdm={0,31,59,90,120,151,181,212,243,273,304,334};int gy2=gy-1600,gm2=gm-1,gd2=gd-1;long gdn=365L*gy2+(gy2+3)/4-(gy2+99)/100+(gy2+399)/400+gdm[gm2]+gd2;if(gm2>1&&((gy%4==0&&gy%100!=0)||(gy%400==0)))gdn++;long jdn=gdn-79;long jnp=jdn/12053;jdn%=12053;int jy=(int)(979+33*jnp+4*(jdn/1461));jdn%=1461;if(jdn>=366){jy+=(jdn-1)/365;jdn=(jdn-1)%365;}int jm,jd;if(jdn<186){jm=1+(int)(jdn/31);jd=1+(int)(jdn%31);}else{jm=7+(int)((jdn-186)/30);jd=1+(int)((jdn-186)%30);}return new int[]{jy,jm,jd};}void saveDay(){sp.edit().putString("day",key()).putInt("today",today).putInt("todayDone",todayDone).apply();}void save(){sp.edit().putInt("idx",idx).putInt("cnt",cnt).putInt("st",st).putInt("total",total).putInt("done",done).putBoolean("vib",vib).putBoolean("fin",fin).putBoolean("keep",keep).putBoolean("one",one).putBoolean("dark",dark).apply();}int parse(String s,int def){try{return Integer.parseInt(s.trim());}catch(Exception e){return def;}}
 void loadCu(){cu.clear();try{JSONArray a=new JSONArray(sp.getString("cu","[]"));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);cu.add(new Z(o.optString("t"),o.optString("a"),o.optString("s"),o.optInt("g",100),"شخصی",true));}}catch(Exception e){}}void saveCu(){try{JSONArray a=new JSONArray();for(Z z:cu){JSONObject o=new JSONObject();o.put("t",z.t);o.put("a",z.a);o.put("s",z.s);o.put("g",z.g);a.put(o);}sp.edit().putString("cu",a.toString()).apply();}catch(Exception e){}}
